\documentclass[11pt]{article}
\usepackage[T1]{fontenc}
\usepackage[utf8]{inputenc}
\usepackage{amsmath,amssymb,amsthm,geometry,booktabs,microtype}
\geometry{margin=1in}
\newtheorem{theorem}{Theorem}[section]
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{corollary}[theorem]{Corollary}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}
\theoremstyle{remark}
\newtheorem{remark}[theorem]{Remark}
\title{Euler Characteristic, Discrete Gauss--Bonnet,\\and Critical-Cell Index Theory}
\author{Aristotle}
\date{26 July 2026}

\begin{document}
\maketitle

\begin{abstract}
We develop a self-contained finite theory linking the Euler characteristic of two-dimensional cell complexes, angle-defect curvature on closed triangulated surfaces, and the alternating index of critical cells in discrete vector fields. The characteristic $\chi=V-E+F$ is invariant under elementary subdivisions and arbitrary finite histories of them. For a closed triangular surface, double counting proves $\sum_vK(v)=2\pi\chi$. For admissible adjacent-dimensional cell pairings, the critical counts satisfy $c_0-c_1+c_2=\chi$. Hence total curvature is $2\pi$ times the critical-cell index. For closed connected orientable surfaces, $\chi=2-2g$ yields total curvature $4\pi(1-g)$, genus rigidity, sign obstructions, and sphere and torus characterizations. We also give algorithms, complexity bounds, numerical examples, and precise limitations.
\end{abstract}

\section{Introduction}
The Euler characteristic has three complementary interpretations: an alternating count of cells, a total curvature, and an index of critical behavior. This paper derives these interpretations in a finite setting using only cell counts, triangular incidence, angle sums, and admissible pairings.

The geometric object is a finite closed triangular surface. Each face has three assigned angles summing to $\pi$, and every edge is incident to two faces. The latter condition is globally expressed by $3F=2E$. No embedding in Euclidean space is required. The dynamical object is an adjacent-dimensional pairing: vertices may pair with edges and edges with faces. The resulting index identity is numerical; acyclicity is required only for stronger homological conclusions.

The central equality is
\[
 \sum_vK(v)=2\pi\chi=2\pi(c_0-c_1+c_2).
\]
For a closed connected orientable surface of genus $g$, this becomes
\[
 \sum_vK(v)=4\pi(1-g).
\]

\section{Finite complexes and subdivision}
\begin{definition}
A finite two-dimensional cell complex in the counting model consists of finite sets of vertices, edges, and faces. If their cardinalities are $V,E,F$, its Euler characteristic is
\[
 \chi=V-E+F.
\]
\end{definition}

Four elementary moves will be used. An edge split sends $(V,E,F)$ to $(V+1,E+1,F)$. A face split sends it to $(V,E+1,F+1)$. A stellar subdivision of an edge shared by two triangles sends it to $(V+1,E+3,F+2)$. Inserting a vertex in a triangle and joining it to the three corners has the same change. A subdivision history is any finite sequence of these moves, including the empty sequence.

\begin{theorem}[Elementary subdivision invariance]
Each of the four elementary moves preserves Euler characteristic.
\end{theorem}
\begin{proof}
The respective changes in $V-E+F$ are $1-1$, $-1+1$, and $1-3+2$ for each of the final two moves. All are zero.
\end{proof}

\begin{theorem}[Finite-history invariance]
If $Y$ is obtained from $X$ by any finite subdivision history, then $\chi(X)=\chi(Y)$.
\end{theorem}
\begin{proof}
Induct on the length of the history. The empty history is immediate. Appending one move preserves the value by elementary invariance, so equality composes through the sequence.
\end{proof}

This theorem applies to histories built from the stated moves. Connecting arbitrary triangulations of the same piecewise-linear surface requires an additional common-refinement theorem.

\begin{theorem}[Two-set excision]
For finite face systems $A$ and $B$, the alternating face-count characteristic satisfies
\[
 \chi(A\cup B)+\chi(A\cap B)=\chi(A)+\chi(B).
\]
\end{theorem}
\begin{proof}
For every face, the sum of its membership indicators in $A\cup B$ and $A\cap B$ equals the sum of its indicators in $A$ and $B$. Multiply by the alternating dimensional sign and sum.
\end{proof}

\section{Angle defect and discrete Gauss--Bonnet}
\begin{definition}
A finite closed triangulated surface with angle data has finite vertex, edge, and face sets, three corners on each face, and a real angle $\theta_{f,i}$ at each corner. It satisfies
\[
 \sum_{i=1}^3\theta_{f,i}=\pi\quad\text{for every face }f,
 \qquad 3F=2E.
\]
At a vertex $v$, its angle-defect curvature is
\[
 K(v)=2\pi-\sum_{(f,i)\mapsto v}\theta_{f,i}.
\]
\end{definition}

\begin{lemma}[Corner indicator collapse]
For a fixed face corner $(f,i)$, summing its angle over all vertices with the indicator that the corner occupies that vertex gives $\theta_{f,i}$.
\end{lemma}
\begin{proof}
Exactly one vertex is occupied by the corner; its indicator is one and all others are zero.
\end{proof}

\begin{lemma}[Angle double counting]
The sum over vertices of all incident corner contributions equals the sum over all face corners:
\[
\sum_v\sum_f\sum_i \mathbf{1}_{(f,i)\mapsto v}\theta_{f,i}
 =\sum_f\sum_i\theta_{f,i}.
\]
\end{lemma}
\begin{proof}
Interchange the finite sums and apply the corner indicator lemma to each corner.
\end{proof}

\begin{lemma}[Total face angle]
The total of all face angles equals $\pi F$.
\end{lemma}
\begin{proof}
Sum the angle-sum identity over all $F$ faces.
\end{proof}

\begin{lemma}[Incidence algebra]
If $3F=2E$, then
\[
2\pi V-\pi F=2\pi(V-E+F).
\]
\end{lemma}
\begin{proof}
The difference of the two sides is $\pi(2E-3F)$.
\end{proof}

\begin{theorem}[Discrete Gauss--Bonnet]
Every finite closed triangulated surface with the preceding angle data satisfies
\[
 \sum_vK(v)=2\pi\chi.
\]
\end{theorem}
\begin{proof}
Expanding the defects gives $2\pi V$ minus the sum of all incident corner angles. Double counting replaces this by the sum over all face corners, and the face-angle lemma makes it $\pi F$. Incidence algebra then gives
\[
 \sum_vK(v)=2\pi V-\pi F=2\pi(V-E+F).
\]
\end{proof}

For a smooth compact surface, the analogous statement is $\int_MK\,dA=2\pi\chi(M)$. Here curvature is an atomic measure supported at vertices. Convergence from atomic defect measures to smooth curvature requires geometric approximation hypotheses beyond this finite theorem.

\section{Critical cells and Poincar\'e--Hopf}
\begin{definition}
For a complex with counts $(V,E,F)$, an admissible numerical pairing field has $p$ vertex--edge pairs and $q$ edge--face pairs satisfying
\[
p\le V,\qquad p+q\le E,\qquad q\le F.
\]
Its critical counts are
\[
c_0=V-p,\qquad c_1=E-p-q,\qquad c_2=F-q.
\]
\end{definition}
The admissibility inequalities imply that all three critical counts are nonnegative.

\begin{theorem}[Discrete Poincar\'e--Hopf identity]
Every admissible pairing field satisfies
\[
c_0-c_1+c_2=\chi.
\]
\end{theorem}
\begin{proof}
Substitution gives
\[
(V-p)-(E-p-q)+(F-q)=V-E+F.
\]
Every adjacent-dimensional pair cancels because neighboring dimensions carry opposite signs.
\end{proof}

\begin{corollary}[Absolute critical-cell bound]
Every admissible pairing field satisfies
\[
 |\chi|\le c_0+c_1+c_2.
\]
\end{corollary}
\begin{proof}
Use the triangle inequality on $|c_0-c_1+c_2|$ and nonnegativity of the critical counts.
\end{proof}

\begin{corollary}[Critical-edge dominance]
If $\chi\le0$, then $c_0+c_2\le c_1$.
\end{corollary}
\begin{proof}
Rearrange the index identity.
\end{proof}

The identity above is numerical. To conclude that critical cells generate a chain complex with the same homology requires actual incidence-compatible pairings and acyclicity.

\section{The curvature--index bridge}
\begin{theorem}[Discrete Gauss--Bonnet--Poincar\'e--Hopf]
If a finite closed triangulated surface carries angle data and an admissible pairing field, then
\[
 \sum_vK(v)=2\pi(c_0-c_1+c_2).
\]
\end{theorem}
\begin{proof}
Both sides equal $2\pi\chi$ by the preceding two theorems.
\end{proof}

\begin{corollary}
Positive total defect implies positive critical index. Moreover,
\[
\sum_vK(v)=0\quad\Longleftrightarrow\quad c_0-c_1+c_2=0.
\]
\end{corollary}
\begin{proof}
Divide by the positive, nonzero constant $2\pi$.
\end{proof}

This theorem identifies global totals. It does not assign the defect of an individual vertex to an individual critical cell.

\section{Genus classification}
For a closed connected orientable surface, genus $g\in\mathbb{Z}_{\ge0}$ counts handles and
\[
\chi=2-2g,\qquad g=\frac{2-\chi}{2}.
\]
Closedness, connectedness, and orientability are geometric hypotheses; parity of $\chi$ alone is not a substitute for them.

\begin{theorem}[Curvature--genus formula]
For a closed connected orientable triangulated surface of genus $g$,
\[
 \sum_vK(v)=2\pi(2-2g)=4\pi(1-g).
\]
\end{theorem}
\begin{proof}
Substitute $\chi=2-2g$ into discrete Gauss--Bonnet.
\end{proof}

\begin{theorem}[Genus rigidity]
Two closed connected orientable triangulated surfaces with equal total angle defect have equal genus.
\end{theorem}
\begin{proof}
Their totals are $4\pi(1-g_1)$ and $4\pi(1-g_2)$. Equality and $4\pi\ne0$ give $g_1=g_2$.
\end{proof}

\begin{theorem}[Sign and zero characterizations]
For a closed connected orientable triangulated surface: positive total defect forces $g=0$; zero total defect is equivalent to $g=1$; and $g\ge1$ forces both $\chi\le0$ and total defect at most zero.
\end{theorem}
\begin{proof}
All claims follow from the sign of $4\pi(1-g)$ and the nonnegative integrality of $g$.
\end{proof}

Thus the sphere has $\chi=2$ and total defect $4\pi$, the torus has both totals zero, and each added handle lowers Euler characteristic by $2$ and total curvature by $4\pi$. Distinct genera therefore lie on a curvature lattice with spacing $4\pi$.

\section{Algorithms}
Given $(V,E,F)$, computing $\chi=V-E+F$ takes constant arithmetic time once counts are available; extracting the counts from lists is linear in input size. For a purported closed triangular mesh, the exact test $3F=2E$ detects a failure of the global incidence requirement, though passing it alone does not prove manifoldness.

To compute total defect, initialize an angle accumulator at every vertex, traverse all $3F$ corners, add each angle to its vertex, and return the sum of $2\pi$ minus every accumulator. This uses $O(V+F)$ time and $O(V)$ auxiliary memory. Every face angle sum should also be checked against $\pi$.

Given $(V,E,F,p,q)$, validate $p\le V$, $p+q\le E$, and $q\le F$. Compute $(c_0,c_1,c_2)$ and its alternating index in constant time. A three-way certificate records
\[
r_{\rm inc}=3F-2E,
\quad r_{\rm GB}=\sum_vK(v)-2\pi\chi,
\quad r_{\rm PH}=c_0-c_1+c_2-\chi.
\]
Exact combinatorics gives zero incidence and index residuals; floating-point curvature should give a Gauss--Bonnet residual near zero within a stated tolerance.

\section{Numerical examples}
\begin{center}
\begin{tabular}{lrrrr}
\toprule
Surface model & $V$ & $E$ & $F$ & $\chi$\\
\midrule
Tetrahedral sphere & 4 & 6 & 4 & 2\\
Octahedral sphere & 6 & 12 & 8 & 2\\
Icosahedral sphere & 12 & 30 & 20 & 2\\
Seven-vertex torus & 7 & 21 & 14 & 0\\
Genus-two mesh & 10 & 30 & 18 & $-2$\\
\bottomrule
\end{tabular}
\end{center}

For the regular tetrahedron, three angles of $\pi/3$ meet at each vertex. Every defect is $\pi$, so the total is $4\pi$. The torus counts force total defect zero. The genus-two counts force total defect $-4\pi$. If the genus-two mesh has $p=9$ and $q=17$, then
\[
(c_0,c_1,c_2)=(1,4,1),\qquad c_0-c_1+c_2=-2,
\]
which agrees with its Euler characteristic and curvature.

\section{Applications, limitations, and future work}
The formulas provide inexpensive diagnostics for mesh processing. Incidence checks connectivity counts, Gauss--Bonnet compares geometry with topology, and Poincar\'e--Hopf checks pairing counts. Subdivision invariance makes these diagnostics stable across resolution, while excision permits local computations to be combined with overlap correction. Smoothing may move angle defects but cannot alter their total without changing topology or leaving the hypotheses.

The scope is precise. The pairing identity does not establish homological equivalence. The genus results assume the classification formula for closed connected orientable surfaces. The curvature theorem is finite and does not itself prove the smooth analytic result. Boundary surfaces require boundary-turning terms, and nonorientable surfaces require a different classification parameter.

Natural extensions include proving that arbitrary triangulations of the same compact piecewise-linear surface are linked by stellar moves and inverse moves; upgrading acyclic incidence-compatible pairings to chain-homotopy cancellation; proving weak convergence of angle-defect measures under shape-regular refinement; localizing curvature at critical cells; and establishing a boundary Gauss--Bonnet--Poincar\'e--Hopf correspondence.

\section{Conclusion}
Cell refinement, angle geometry, and adjacent-dimensional pairing all preserve or recover one integer. In the finite closed orientable setting their common ledger is
\[
\sum_vK(v)=2\pi\chi=2\pi(c_0-c_1+c_2)=4\pi(1-g).
\]
The identities are exact, transparent, computationally efficient, and stable under arbitrary finite histories of the stated subdivision moves.

\end{document}

