from math import pi
from typing import Final
MESHES: Final[dict[str, tuple[int, int, int]]] = {
    "tetrahedron": (4, 6, 4), "octahedron": (6, 12, 8),
    "icosahedron": (12, 30, 20), "torus": (7, 21, 14),
    "genus two": (10, 30, 18),
}
def summarize(name: str, counts: tuple[int, int, int]) -> str:
    v, e, f = counts; chi = v - e + f
    return f"{name}: chi={chi}, total defect={2*pi*chi:.9f}"
if __name__ == "__main__":
    for name, counts in MESHES.items(): print(summarize(name, counts))

from math import isclose, pi
from typing import Sequence
def defects(angle_sums: Sequence[float]) -> list[float]:
    return [2*pi-s for s in angle_sums]
def verify_tetrahedron() -> None:
    values = defects([pi, pi, pi, pi])
    print("defects:", values, "total:", sum(values))
    assert all(isclose(x, pi) for x in values)
    assert isclose(sum(values), 4*pi)
if __name__ == "__main__": verify_tetrahedron()

from dataclasses import dataclass
@dataclass(frozen=True)
class CriticalCounts:
    c0: int; c1: int; c2: int
    def index(self) -> int: return self.c0-self.c1+self.c2
def compute(v: int, e: int, f: int, p: int, q: int) -> CriticalCounts:
    if not (0 <= p <= v and 0 <= q <= f and p+q <= e):
        raise ValueError("inadmissible pairing counts")
    return CriticalCounts(v-p, e-p-q, f-q)
if __name__ == "__main__":
    c = compute(10, 30, 18, 9, 17)
    print(c, "index=", c.index()); assert c.index() == -2

