from typing import Iterable
def euler_characteristic(cells_by_dimension: Iterable[int]) -> int:
    return sum((1 if d % 2 == 0 else -1) * n
               for d, n in enumerate(cells_by_dimension))

from math import pi
from typing import Sequence
def total_defect(corners_at_vertices: Sequence[Sequence[float]]) -> float:
    return sum(2*pi-sum(corners) for corners in corners_at_vertices)

from dataclasses import dataclass
@dataclass(frozen=True)
class Certificate:
    incidence: int; poincare_hopf: int; gauss_bonnet: float
def certify(v: int, e: int, f: int, c0: int, c1: int, c2: int,
            measured_curvature: float) -> Certificate:
    chi = v-e+f
    from math import pi
    return Certificate(3*f-2*e, c0-c1+c2-chi,
                       measured_curvature-2*pi*chi)

